export default function App() {
  const [screen, setScreen] = useState("login"); // login | home | checklist | history
  const [hazirlaniyor, setHazirlaniyor] = useState(true);
  const [, setTick] = useState(0); // saat 08:00/16:00 sınırını canlı takip etmek için

  // Giriş alanları
  const [hotelCode, setHotelCode] = useState("");
  const [userCode, setUserCode] = useState("");
  const [password, setPassword] = useState("");
  const [girisHatasi, setGirisHatasi] = useState("");
  const [girisYukleniyor, setGirisYukleniyor] = useState(false);

  const [currentUser, setCurrentUser] = useState(null);
  const [record, setRecord] = useState(null); // bugünün kontrol listesi kaydı
  const [kayitYukleniyor, setKayitYukleniyor] = useState(false);
  const [listeHatasi, setListeHatasi] = useState("");
  const [bitiriliyor, setBitiriliyor] = useState(false);
  const [tamamlandiMesaji, setTamamlandiMesaji] = useState(false);

  // Geçmiş
  const [gecmisKayitlar, setGecmisKayitlar] = useState([]);
  const [gecmisYukleniyor, setGecmisYukleniyor] = useState(false);

  // Gün sonu raporu
  const [raporPaneliAcik, setRaporPaneliAcik] = useState(false);
  const [raporEposta, setRaporEposta] = useState("");
  const [raporMesaj, setRaporMesaj] = useState("");
  const [raporIsleniyor, setRaporIsleniyor] = useState(false);

  // Saatli hatırlatma / bildirim izni
  const [bildirimDurumu, setBildirimDurumu] = useState(
    typeof Notification !== "undefined" ? Notification.permission : "unsupported"
  );

  const fileInputRefs = useRef({});
  const autosaveTimer = useRef(null);

  function bildirimIzniIste() {
    if (typeof Notification === "undefined") return;
    Notification.requestPermission().then((sonuc) => setBildirimDurumu(sonuc));
  }

  // Her ekranda görünen, kısa süreli onay mesajı (örn. "Kaydedildi")
  const [toast, setToast] = useState(null);
  const toastTimer = useRef(null);
  function toastGoster(mesaj) {
    setToast(mesaj);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(null), 3500);
  }

  // PDF için yedek bağlantı: otomatik indirme çalışmazsa (bazı Android
  // tarayıcılarında "yüklü uygulama" modunda indirme engellenebiliyor)
  // kullanıcı bu bağlantıya dokunup PDF'i açabilir/indirebilir.
  const [pdfLinkUrl, setPdfLinkUrl] = useState(null);
  const [pdfLinkAdi, setPdfLinkAdi] = useState("");

  useEffect(() => {
    seedData();
    const script = document.createElement("script");
    script.src = JSPDF_URL;
    document.body.appendChild(script);
    const zamanlayici = setInterval(() => setTick((x) => x + 1), 60000);
    return () => clearInterval(zamanlayici);
  }, []);

  async function seedData() {
    for (const h of OTELLER_BASLANGIC) {
      const mevcut = await safeGet(`hotels:${h.code}`, true);
      if (!mevcut) await window.storage.set(`hotels:${h.code}`, JSON.stringify(h), true);
    }
    for (const u of KULLANICILAR_BASLANGIC) {
      const mevcut = await safeGet(`users:${u.hotelCode}:${u.userCode}`, true);
      if (!mevcut)
        await window.storage.set(`users:${u.hotelCode}:${u.userCode}`, JSON.stringify(u), true);
    }
    setHazirlaniyor(false);
  }

  function digitInput(value, setter) {
    setter(value.replace(/\D/g, "").slice(0, 4));
  }

  async function handleLogin() {
    setGirisHatasi("");
    if (hotelCode.length !== 4 || userCode.length !== 4 || password.length !== 4) {
      setGirisHatasi("Otel kodu, kullanıcı kodu ve şifre 4 haneli olmalıdır.");
      return;
    }
    setGirisYukleniyor(true);
    const hotelRes = await safeGet(`hotels:${hotelCode}`, true);
    if (!hotelRes) {
      setGirisHatasi("Otel kodu bulunamadı.");
      setGirisYukleniyor(false);
      return;
    }
    const userRes = await safeGet(`users:${hotelCode}:${userCode}`, true);
    if (!userRes) {
      setGirisHatasi("Kullanıcı kodu bulunamadı.");
      setGirisYukleniyor(false);
      return;
    }
    const hotel = JSON.parse(hotelRes.value);
    const user = JSON.parse(userRes.value);
    if (user.password !== password) {
      setGirisHatasi("Şifre hatalı.");
      setGirisYukleniyor(false);
      return;
    }
    const tamUser = { ...user, hotelName: hotel.name };
    setCurrentUser(tamUser);
    setGirisYukleniyor(false);
    setScreen("home");
    await bugununKaydiniYukle(tamUser);
  }

  function handleLogout() {
    setCurrentUser(null);
    setRecord(null);
    setHotelCode("");
    setUserCode("");
    setPassword("");
    setRaporPaneliAcik(false);
    setRaporMesaj("");
    setScreen("login");
  }

  async function bugununKaydiniYukle(user) {
    setKayitYukleniyor(true);
    const tarih = bugunTarihi();
    const key = `checklist:${user.hotelCode}:${user.department}:${tarih}`;
    const mevcut = await safeGet(key, true);
    if (mevcut) {
      const veri = JSON.parse(mevcut.value);
      const guncelSablon = DEPARTMAN_LISTELERI[user.department] || [];
      const eskiListeyleUyumsuz =
        !veri.tasks || veri.tasks.length !== guncelSablon.length;
      if (!eskiListeyleUyumsuz) {
        veri.tasks = veri.tasks.map((t) => ({ zaman: null, ...t }));
        veri.remindedTasks = veri.remindedTasks || [];
        setRecord(veri);
        setKayitYukleniyor(false);
        return;
      }
      // Kontrol listesi güncellendiği için (madde sayısı değişti), bu güne ait
      // eski kayıt yeni şablona göre sıfırdan oluşturuluyor.
    }
    const sablon = DEPARTMAN_LISTELERI[user.department];
    if (!sablon) {
      setRecord(null);
      setKayitYukleniyor(false);
      return;
    }
    setRecord({
      key,
      date: tarih,
      hotelCode: user.hotelCode,
      hotelName: user.hotelName,
      department: user.department,
      userCode: user.userCode,
      userName: user.name,
      tasks: sablon.map((text, i) => ({ id: i + 1, text, status: null, zaman: null, aciklama: "", photo: null })),
      remindedTasks: [],
      tamamlandiMi: false,
      tamamlanmaZamani: null,
      sonGuncelleme: new Date().toISOString(),
    });
    setKayitYukleniyor(false);
  }

  // Otomatik kaydetme: kontrol listesi ekranındayken her değişiklikte
  // kısa bir gecikmeyle arka planda kaydeder. "Bitir" tuşuna basılmasa da
  // veriler kaybolmaz; 08:00-16:00 arasında istediği zaman kaldığı yerden devam edebilir.
  useEffect(() => {
    if (!record || screen !== "checklist") return;
    if (autosaveTimer.current) clearTimeout(autosaveTimer.current);
    autosaveTimer.current = setTimeout(() => {
      window.storage.set(
        record.key,
        JSON.stringify({ ...record, sonGuncelleme: new Date().toISOString() }),
        true
      );
    }, 600);
    return () => clearTimeout(autosaveTimer.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [record]);

  // Saatli hatırlatma kontrolü: HATIRLATMALAR'da tanımlı bir madde, tanımlı
  // saati geçtiği halde hâlâ işaretlenmediyse bir kere bildirim gönderir.
  // NOT: Bu bildirim yalnızca uygulama açıkken (ön planda ya da arka plan
  // sekmesinde) çalışır; tarayıcı tamamen kapalıyken gerçek bir OS alarmı
  // gibi çalışmaz (bunun için sunucu taraflı push bildirimi gerekir).
  useEffect(() => {
    if (!record) return;
    const hatirlatmalar = HATIRLATMALAR[record.department];
    if (!hatirlatmalar) return;
    const zatenBildirilenler = record.remindedTasks || [];
    const yeniBildirilecekler = [];
    record.tasks.forEach((t) => {
      const saat = hatirlatmalar[t.id];
      if (saat && !t.status && saatGectiMi(saat) && !zatenBildirilenler.includes(t.id)) {
        yeniBildirilecekler.push({ id: t.id, text: t.text, saat });
      }
    });
    if (yeniBildirilecekler.length === 0) return;

    yeniBildirilecekler.forEach((b) => {
      if (typeof Notification !== "undefined" && Notification.permission === "granted") {
        try {
          new Notification("Kontrol Hatırlatması", {
            body: `"${b.text}" maddesi saat ${b.saat} itibarıyla tamamlanmış olmalıydı, henüz işaretlenmedi.`,
            icon: "icon-192.png",
          });
        } catch (e) {}
      }
    });

    setRecord((prev) => ({
      ...prev,
      remindedTasks: [...(prev.remindedTasks || []), ...yeniBildirilecekler.map((b) => b.id)],
    }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [record]);

  function setStatus(id, status) {
    setRecord((prev) => ({
      ...prev,
      tasks: prev.tasks.map((t) => {
        if (t.id !== id) return t;
        const yeniDurum = t.status === status ? null : status;
        return {
          ...t,
          status: yeniDurum,
          zaman: yeniDurum ? new Date().toLocaleTimeString("tr-TR", { hour12: false }) : null,
        };
      }),
    }));
  }

  function setAciklama(id, value) {
    setRecord((prev) => ({
      ...prev,
      tasks: prev.tasks.map((t) => (t.id === id ? { ...t, aciklama: value } : t)),
    }));
  }

  function removePhoto(id) {
    setRecord((prev) => ({
      ...prev,
      tasks: prev.tasks.map((t) => (t.id === id ? { ...t, photo: null } : t)),
    }));
  }

  function handlePhotoSelect(id, file) {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const maxW = 700;
        const scale = Math.min(1, maxW / img.width);
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL("image/jpeg", 0.6);
        setRecord((prev) => ({
          ...prev,
          tasks: prev.tasks.map((t) => (t.id === id ? { ...t, photo: dataUrl } : t)),
        }));
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  }

  async function handleBitir() {
    setListeHatasi("");
    setBitiriliyor(true);
    const guncel = {
      ...record,
      tamamlandiMi: true,
      tamamlanmaZamani: new Date().toISOString(),
      sonGuncelleme: new Date().toISOString(),
    };
    try {
      await window.storage.set(guncel.key, JSON.stringify(guncel), true);
      setRecord(guncel);
      setTamamlandiMesaji(true);
      const isaretliSayisi = guncel.tasks.filter((t) => t.status).length;
      toastGoster(`✓ Kaydedildi — ${isaretliSayisi}/${guncel.tasks.length} madde işaretli`);
      setTimeout(() => setTamamlandiMesaji(false), 2500);
    } catch (e) {
      setListeHatasi("Kaydetme sırasında bir hata oluştu. Lütfen tekrar deneyin.");
      toastGoster("⚠ Kaydetme sırasında bir hata oluştu.");
    }
    setBitiriliyor(false);
  }

  async function gecmisiGetir() {
    setGecmisYukleniyor(true);
    setGecmisKayitlar([]);
    try {
      const liste = await window.storage.list(
        `checklist:${currentUser.hotelCode}:${currentUser.department}:`,
        true
      );
      const keys = (liste && liste.keys) || [];
      const kayitlar = [];
      for (const k of keys.slice(-31)) {
        const r = await safeGet(k, true);
        if (r) {
          try {
            kayitlar.push(JSON.parse(r.value));
          } catch (e) {}
        }
      }
      kayitlar.sort((a, b) => (a.date < b.date ? 1 : -1));
      setGecmisKayitlar(kayitlar);
    } catch (e) {
      setGecmisKayitlar([]);
    }
    setGecmisYukleniyor(false);
  }

  function gecmiseGit() {
    setScreen("history");
    gecmisiGetir();
  }

  /* ---------------- PDF OLUŞTURMA ---------------- */

  function jsPdfHazirMi() {
    return typeof window !== "undefined" && window.jspdf && window.jspdf.jsPDF;
  }

  function pdfFontYukle(doc) {
    // Türkçe karakterleri (ş, ğ, ı, İ, ö, ü, ç) doğru gösterebilmek için
    // jsPDF'in varsayılan Helvetica fontu yerine, gömülü Türkçe destekli
    // bir font (Liberation Sans, subset edilmiş) kullanılıyor.
    try {
      doc.addFileToVFS("TurkceFontRegular.ttf", TURKCE_FONT_REGULAR_B64);
      doc.addFont("TurkceFontRegular.ttf", "TurkceFont", "normal");
      doc.addFileToVFS("TurkceFontBold.ttf", TURKCE_FONT_BOLD_B64);
      doc.addFont("TurkceFontBold.ttf", "TurkceFont", "bold");
      return "TurkceFont";
    } catch (e) {
      return "helvetica";
    }
  }

  function pdfOlustur(kayit) {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: "pt", format: "a4" });
    const fontAdi = pdfFontYukle(doc);
    const pageWidth = doc.internal.pageSize.getWidth();
    const pageHeight = doc.internal.pageSize.getHeight();
    const margin = 40;
    let y = margin;

    doc.setFont(fontAdi, "bold");
    doc.setFontSize(16);
    doc.text("Otel Departman Kontrol Listesi", margin, y);
    y += 22;

    doc.setFont(fontAdi, "normal");
    doc.setFontSize(11);
    doc.text(`Otel: ${kayit.hotelName}  (Kod: ${kayit.hotelCode})`, margin, y);
    y += 16;
    doc.text(`Departman: ${kayit.department}`, margin, y);
    y += 16;
    doc.text(`Tarih: ${formatTarihSadece(kayit.date)}`, margin, y);
    y += 16;
    doc.text(`Kontrol eden: ${kayit.userName} (Kullanıcı Kodu: ${kayit.userCode})`, margin, y);
    y += 16;
    const durumYazi = kayit.tamamlandiMi ? "Tamamlandı" : "Süre içinde tamamlanmadı / otomatik kaydedildi";
    doc.text(`Durum: ${durumYazi}`, margin, y);
    y += 26;

    kayit.tasks.forEach((t) => {
      if (y + 40 > pageHeight - margin) {
        doc.addPage();
        y = margin;
      }
      doc.setFont(fontAdi, "bold");
      doc.setFontSize(11);
      const baslikSatirlari = doc.splitTextToSize(`${t.id}. ${t.text}`, pageWidth - margin * 2);
      doc.text(baslikSatirlari, margin, y);
      y += baslikSatirlari.length * 14;

      doc.setFont(fontAdi, "normal");
      doc.setFontSize(10);
      const durum = t.status === "olumlu" ? "OLUMLU" : t.status === "olumsuz" ? "OLUMSUZ" : "İşaretlenmedi";
      const zamanEki = t.zaman ? `  (Saat: ${t.zaman})` : "";
      doc.text(`Durum: ${durum}${zamanEki}`, margin, y);
      y += 14;

      if (t.aciklama) {
        const aciklamaSatirlari = doc.splitTextToSize(`Açıklama: ${t.aciklama}`, pageWidth - margin * 2);
        if (y + aciklamaSatirlari.length * 13 > pageHeight - margin) {
          doc.addPage();
          y = margin;
        }
        doc.text(aciklamaSatirlari, margin, y);
        y += aciklamaSatirlari.length * 13;
      }

      if (t.photo) {
        if (y + 110 > pageHeight - margin) {
          doc.addPage();
          y = margin;
        }
        try {
          doc.addImage(t.photo, "JPEG", margin, y, 100, 100);
        } catch (e) {}
        y += 112;
      }
      y += 8;
    });

    return doc;
  }

  async function raporOlusturVeGonder(kayit) {
    setRaporMesaj("");
    setPdfLinkUrl(null);
    if (!kayit) {
      setRaporMesaj("Bu gün için kaydedilmiş bir kontrol listesi bulunamadı.");
      return;
    }
    if (!jsPdfHazirMi()) {
      setRaporMesaj("PDF oluşturucu henüz hazırlanıyor, birkaç saniye sonra tekrar deneyin.");
      return;
    }
    setRaporIsleniyor(true);
    setRaporMesaj("PDF hazırlanıyor…");
    try {
      const doc = pdfOlustur(kayit);
      const dosyaAdi = `kontrol-listesi-${kayit.hotelCode}-${kayit.date}.pdf`;
      const konuMetni = `${kayit.hotelName} - ${kayit.department} Kontrol Listesi - ${formatTarihSadece(kayit.date)}`;

      // Yedek bağlantı: otomatik indirme telefonda/tarayıcıda engellenirse
      // veya fark edilmezse, kullanıcı bu bağlantıya dokunarak PDF'i her zaman
      // açabilir/indirebilir.
      try {
        const blobUrl = doc.output("bloburl");
        setPdfLinkUrl(blobUrl.toString ? blobUrl.toString() : blobUrl);
        setPdfLinkAdi(dosyaAdi);
      } catch (e) {}

      if (BACKEND_URL) {
        if (!raporEposta.trim()) {
          setRaporMesaj("Lütfen alıcı e-posta adresini girin.");
          setRaporIsleniyor(false);
          return;
        }
        const pdfBase64 = doc.output("datauristring").split(",")[1];
        const yanit = await fetch(BACKEND_URL, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            to: raporEposta.trim(),
            subject: konuMetni,
            hotelName: kayit.hotelName,
            department: kayit.department,
            date: kayit.date,
            fileName: dosyaAdi,
            pdfBase64,
          }),
        });
        if (yanit.ok) {
          setRaporMesaj("E-posta başarıyla gönderildi.");
          toastGoster("✓ E-posta gönderildi");
        } else {
          setRaporMesaj("Sunucu e-postayı gönderirken bir hata döndürdü.");
        }
      } else {
        let indirmeBasarili = true;
        try {
          doc.save(dosyaAdi);
        } catch (e) {
          indirmeBasarili = false;
        }

        if (raporEposta.trim()) {
          const konu = encodeURIComponent(konuMetni);
          const govde = encodeURIComponent(
            `Merhaba,\n\n${formatTarihSadece(kayit.date)} tarihli ${kayit.department} departmanı kontrol listesi PDF olarak cihaza indirildi.\nLütfen e-posta uygulamasında az önce indirilen "${dosyaAdi}" dosyasını bu mesaja ekleyip gönderin.\n\nOtel: ${kayit.hotelName}\nKontrol eden: ${kayit.userName}`
          );
          window.location.href = `mailto:${raporEposta.trim()}?subject=${konu}&body=${govde}`;
        }

        if (indirmeBasarili) {
          setRaporMesaj(
            raporEposta.trim()
              ? "PDF indirildi ve e-posta uygulamanız açıldı. Lütfen indirilen dosyayı mesaja ekleyip gönderin."
              : "PDF indirildi. İnmediyse aşağıdaki bağlantıya dokunun."
          );
          toastGoster("✓ PDF hazır");
        } else {
          setRaporMesaj("Otomatik indirme başlamadı. Lütfen aşağıdaki bağlantıya dokunup PDF'i açın.");
        }
      }
    } catch (e) {
      setRaporMesaj("Rapor oluşturulurken bir hata oluştu: " + (e && e.message ? e.message : String(e)));
    }
    setRaporIsleniyor(false);
  }

  const durum = pencereDurumu();
  const tamamlanan = record ? record.tasks.filter((t) => t.status).length : 0;
  const toplamMadde = record ? record.tasks.length : 0;
  const duzenlenebilir = durum === "aktif";

  return (
    <div style={styles.sayfaDisi}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Sora:wght@500;600;700&family=Inter:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; }
        .telefon-govde { font-family: 'Inter', sans-serif; }
        .baslik-font { font-family: 'Sora', sans-serif; }
        input:focus, textarea:focus, button:focus-visible {
          outline: 2px solid #B08D3E;
          outline-offset: 2px;
        }
        .kod-input::placeholder { color: #A9A398; letter-spacing: 0.3em; }
        @media (prefers-reduced-motion: reduce) {
          * { transition: none !important; animation: none !important; }
        }
      `}</style>

      <div className="telefon-govde" style={styles.telefonCerceve}>
        <div style={styles.durumCubugu}>
          <span>{new Date().toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" })}</span>
          <span style={{ letterSpacing: 2 }}>●●●●</span>
        </div>

        {hazirlaniyor ? (
          <div style={styles.merkezYukleniyor}>Hazırlanıyor…</div>
        ) : screen === "login" ? (
          <GirisEkrani
            hotelCode={hotelCode}
            userCode={userCode}
            password={password}
            setHotelCode={(v) => digitInput(v, setHotelCode)}
            setUserCode={(v) => digitInput(v, setUserCode)}
            setPassword={(v) => digitInput(v, setPassword)}
            hata={girisHatasi}
            yukleniyor={girisYukleniyor}
            onGiris={handleLogin}
          />
        ) : screen === "home" ? (
          <AnaSayfa
            user={currentUser}
            record={record}
            kayitYukleniyor={kayitYukleniyor}
            durum={durum}
            tamamlanan={tamamlanan}
            toplamMadde={toplamMadde}
            onBaslat={() => setScreen("checklist")}
            onGecmis={gecmiseGit}
            onCikis={handleLogout}
            raporPaneliAcik={raporPaneliAcik}
            setRaporPaneliAcik={setRaporPaneliAcik}
            raporEposta={raporEposta}
            setRaporEposta={setRaporEposta}
            raporMesaj={raporMesaj}
            raporIsleniyor={raporIsleniyor}
            onRaporGonder={() => raporOlusturVeGonder(record)}
            bildirimDurumu={bildirimDurumu}
            onBildirimIzniIste={bildirimIzniIste}
          />
        ) : screen === "checklist" ? (
          <KontrolListesiEkrani
            user={currentUser}
            record={record}
            duzenlenebilir={duzenlenebilir}
            durum={durum}
            hata={listeHatasi}
            tamamlanan={tamamlanan}
            bitiriliyor={bitiriliyor}
            tamamlandiMesaji={tamamlandiMesaji}
            setStatus={setStatus}
            setAciklama={setAciklama}
            onPhotoSelect={handlePhotoSelect}
            onRemovePhoto={removePhoto}
            onBitir={handleBitir}
            onGeri={() => setScreen("home")}
            fileInputRefs={fileInputRefs}
          />
        ) : screen === "history" ? (
          <GecmisEkrani
            kayitlar={gecmisKayitlar}
            yukleniyor={gecmisYukleniyor}
            onGeri={() => setScreen("home")}
            onPdf={(k) => raporOlusturVeGonder(k)}
            jsPdfHazirMi={jsPdfHazirMi}
          />
        ) : null}

        {toast && !pdfLinkUrl && <div style={styles.toastMesaj}>{toast}</div>}

        {pdfLinkUrl && (
          <div style={styles.pdfBaglantiCubugu}>
            <a href={pdfLinkUrl} target="_blank" rel="noreferrer" style={styles.pdfBaglantiLink}>
              📄 {pdfLinkAdi} — Aç / İndir
            </a>
            <button
              style={styles.pdfBaglantiKapat}
              onClick={() => setPdfLinkUrl(null)}
              aria-label="Kapat"
            >
              ✕
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------
   EKRAN BİLEŞENLERİ
-------------------------------------------------------------------*/

function GirisEkrani({
  hotelCode,
  userCode,
  password,
  setHotelCode,
  setUserCode,
  setPassword,
  hata,
  yukleniyor,
  onGiris,
}) {
  return (
    <div style={styles.icerik}>
      <div style={styles.anahtarKart}>
        <div style={styles.anahtarUst}>
          <span style={styles.anahtarEtiket}>OTEL KONTROL SİSTEMİ</span>
          <div style={styles.manyetikSerit} />
        </div>
        <div className="baslik-font" style={styles.anahtarBaslik}>
          Departman Kontrol Listesi
        </div>
      </div>

      <div style={{ marginTop: 28 }}>
        <Etiket>OTEL KODU</Etiket>
        <input
          className="kod-input"
          style={styles.kodInput}
          inputMode="numeric"
          placeholder="0000"
          maxLength={4}
          value={hotelCode}
          onChange={(e) => setHotelCode(e.target.value)}
        />

        <Etiket>KULLANICI KODU</Etiket>
        <input
          className="kod-input"
          style={styles.kodInput}
          inputMode="numeric"
          placeholder="0000"
          maxLength={4}
          value={userCode}
          onChange={(e) => setUserCode(e.target.value)}
        />

        <Etiket>ŞİFRE</Etiket>
        <input
          className="kod-input"
          style={styles.kodInput}
          inputMode="numeric"
          type="password"
          placeholder="••••"
          maxLength={4}
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />

        {hata && <div style={styles.hataKutusu}>{hata}</div>}

        <button
          style={{ ...styles.anaButon, marginTop: 20, opacity: yukleniyor ? 0.7 : 1 }}
          onClick={onGiris}
          disabled={yukleniyor}
        >
          {yukleniyor ? "Giriş yapılıyor…" : "Giriş Yap"}
        </button>
      </div>
    </div>
  );
}

function AnaSayfa({
  user,
  record,
  kayitYukleniyor,
  durum,
  tamamlanan,
  toplamMadde,
  onBaslat,
  onGecmis,
  onCikis,
  raporPaneliAcik,
  setRaporPaneliAcik,
  raporEposta,
  setRaporEposta,
  raporMesaj,
  raporIsleniyor,
  onRaporGonder,
  bildirimDurumu,
  onBildirimIzniIste,
}) {
  let durumYazisi = "";
  let durumRengi = "#6B7280";
  if (durum === "once") {
    durumYazisi = "Bugünkü kontrol listesi henüz başlamadı (08:00'de açılır)";
  } else if (durum === "aktif") {
    durumYazisi = `Devam ediyor · ${tamamlanan}/${toplamMadde} madde işaretlendi`;
    durumRengi = "#B08D3E";
  } else {
    durumYazisi = record
      ? `Süre doldu (16:00) · ${tamamlanan}/${toplamMadde} madde ile kaydedildi`
      : "Süre doldu (16:00) · bugün için kayıt oluşturulmadı";
    durumRengi = "#B7472A";
  }

  const hatirlatmalar = record ? HATIRLATMALAR[record.department] : null;
  const gecikenler =
    record && hatirlatmalar
      ? record.tasks.filter((t) => hatirlatmalar[t.id] && !t.status && saatGectiMi(hatirlatmalar[t.id]))
      : [];

  return (
    <div style={styles.icerik}>
      <div style={styles.anahtarKart}>
        <div style={styles.anahtarUst}>
          <span style={styles.anahtarEtiket}>{user.hotelName}</span>
          <div style={styles.manyetikSerit} />
        </div>
        <div className="baslik-font" style={styles.anahtarBaslik}>
          Hoş geldiniz, {user.name}
        </div>
        <div style={styles.anahtarAltBilgi}>
          Otel Kodu {user.hotelCode} · Kullanıcı {user.userCode}
        </div>
        <div style={styles.departmanRozeti}>{user.department}</div>
      </div>

      <div style={styles.durumKarti}>
        <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: 0.5, color: "#6B7280" }}>
          BUGÜN · 08:00 – 16:00
        </div>
        <div style={{ fontSize: 14, fontWeight: 600, color: durumRengi, marginTop: 4 }}>
          {kayitYukleniyor ? "Yükleniyor…" : durumYazisi}
        </div>
      </div>

      {gecikenler.length > 0 && (
        <div style={styles.gecikmeBanner}>
          ⏰ {gecikenler.length === 1
            ? `Hatırlatma: "${gecikenler[0].text}" maddesi henüz işaretlenmedi.`
            : `Hatırlatma: ${gecikenler.length} madde zamanında işaretlenmedi.`}
        </div>
      )}

      {bildirimDurumu !== "granted" && bildirimDurumu !== "unsupported" && (
        <button style={styles.bildirimButon} onClick={onBildirimIzniIste}>
          🔔 Saatli Hatırlatma Bildirimlerini Aç
        </button>
      )}

      <div style={{ marginTop: 18, display: "flex", flexDirection: "column", gap: 12 }}>
        <button
          style={{ ...styles.anaButon, opacity: durum === "once" ? 0.5 : 1 }}
          onClick={onBaslat}
          disabled={durum === "once"}
        >
          {durum === "aktif" ? "Kontrol Listesini Aç" : durum === "once" ? "Henüz Başlamadı" : "Bugünün Listesini Görüntüle"}
        </button>
        <button style={styles.ikincilButon} onClick={onGecmis}>
          Geçmiş Kayıtlar
        </button>

        <button
          style={styles.ucuncuButon}
          onClick={() => setRaporPaneliAcik((a) => !a)}
        >
          📄 Gün Sonu Raporunu Oluştur ve E-posta ile Gönder
        </button>

        {raporPaneliAcik && (
          <div style={styles.raporPaneli}>
            <Etiket>YÖNETİCİ E-POSTA ADRESİ</Etiket>
            <input
              style={styles.epostaInput}
              type="email"
              placeholder="ornek@rdmhotels.com"
              value={raporEposta}
              onChange={(e) => setRaporEposta(e.target.value)}
            />
            <button
              style={{ ...styles.anaButon, marginTop: 12, opacity: raporIsleniyor ? 0.7 : 1 }}
              onClick={onRaporGonder}
              disabled={raporIsleniyor}
            >
              {raporIsleniyor ? "Hazırlanıyor…" : "PDF Oluştur ve Gönder"}
            </button>
            {raporMesaj && <div style={styles.bilgiKutusu}>{raporMesaj}</div>}
            <div style={styles.notMetni}>
              Not: Tarayıcı güvenliği nedeniyle e-posta dosya eki otomatik eklenemez;
              PDF cihaza indirilir ve e-posta uygulamanız hazır bir taslakla açılır,
              dosyayı eklemeniz yeterlidir.
            </div>
          </div>
        )}

        <button style={styles.metinButon} onClick={onCikis}>
          Çıkış Yap
        </button>
      </div>
    </div>
  );
}

function KontrolListesiEkrani({
  user,
  record,
  duzenlenebilir,
  durum,
  hata,
  tamamlanan,
  bitiriliyor,
  tamamlandiMesaji,
  setStatus,
  setAciklama,
  onPhotoSelect,
  onRemovePhoto,
  onBitir,
  onGeri,
  fileInputRefs,
}) {
  if (!record) {
    return (
      <div style={styles.icerik}>
        <div style={styles.hataKutusu}>
          "{user.department}" departmanı için tanımlı bir kontrol listesi bulunamadı.
        </div>
        <button style={{ ...styles.ikincilButon, marginTop: 16 }} onClick={onGeri}>
          Ana Sayfaya Dön
        </button>
      </div>
    );
  }

  return (
    <div style={styles.icerik}>
      <div style={styles.listeUstBaslik}>
        <button style={styles.geriButon} onClick={onGeri} aria-label="Geri">
          ←
        </button>
        <div>
          <div className="baslik-font" style={styles.listeBaslikYazi}>
            {user.department} Kontrol Listesi
          </div>
          <div style={styles.ilerlemeYazi}>
            {tamamlanan} / {record.tasks.length} madde işaretlendi
            {!duzenlenebilir && "  ·  Süre doldu, salt okunur"}
          </div>
        </div>
      </div>

      <div style={styles.ilerlemeCubugu}>
        <div
          style={{
            ...styles.ilerlemeDoluluk,
            width: `${(tamamlanan / record.tasks.length) * 100}%`,
          }}
        />
      </div>

      {tamamlandiMesaji && <div style={styles.basariMesaji}>✓ Kontrol listesi kaydedildi</div>}

      <div style={{ display: "flex", flexDirection: "column", gap: 14, marginTop: 14 }}>
        {record.tasks.map((t) => {
          const hatirlatmaSaati = (HATIRLATMALAR[record.department] || {})[t.id];
          const gecikti = hatirlatmaSaati && !t.status && saatGectiMi(hatirlatmaSaati);
          return (
          <div
            key={t.id}
            style={{
              ...styles.gorevKarti,
              ...(gecikti ? styles.gorevKartiUyari : {}),
            }}
          >
            <div style={styles.gorevUst}>
              <div
                style={{
                  ...styles.gorevNumara,
                  background:
                    t.status === "olumlu" ? "#2F7D5C" : t.status === "olumsuz" ? "#B7472A" : "#EFEAE0",
                  color: t.status ? "#fff" : "#16323A",
                }}
              >
                {t.id}
              </div>
              <div style={{ flex: 1 }}>
                <div style={styles.gorevMetin}>{t.text}</div>
                {hatirlatmaSaati && (
                  <div style={{ ...styles.hatirlatmaEtiketi, ...(gecikti ? styles.hatirlatmaGecikti : {}) }}>
                    {gecikti
                      ? `⏰ Hatırlatma: ${hatirlatmaSaati}'a kadar tamamlanmalıydı, henüz işaretlenmedi`
                      : `⏰ ${hatirlatmaSaati}'a kadar tamamlanmalı`}
                  </div>
                )}
              </div>
            </div>

            <div style={styles.secimSatiri}>
              <label
                style={{
                  ...styles.secimKutusu,
                  ...(t.status === "olumlu" ? styles.secimAktifOlumlu : {}),
                  opacity: duzenlenebilir ? 1 : 0.6,
                }}
              >
                <input
                  type="checkbox"
                  checked={t.status === "olumlu"}
                  disabled={!duzenlenebilir}
                  onChange={() => setStatus(t.id, "olumlu")}
                  style={styles.gizliCheckbox}
                />
                OLUMLU
              </label>
              <label
                style={{
                  ...styles.secimKutusu,
                  ...(t.status === "olumsuz" ? styles.secimAktifOlumsuz : {}),
                  opacity: duzenlenebilir ? 1 : 0.6,
                }}
              >
                <input
                  type="checkbox"
                  checked={t.status === "olumsuz"}
                  disabled={!duzenlenebilir}
                  onChange={() => setStatus(t.id, "olumsuz")}
                  style={styles.gizliCheckbox}
                />
                OLUMSUZ
              </label>
            </div>

            {t.zaman && <div style={styles.zamanNotu}>🕒 İşaretlendi: {t.zaman}</div>}

            <textarea
              placeholder={t.status === "olumsuz" ? "Açıklama girin (zorunlu)" : "Açıklama (isteğe bağlı)"}
              value={t.aciklama}
              disabled={!duzenlenebilir}
              onChange={(e) => setAciklama(t.id, e.target.value)}
              style={styles.aciklamaAlani}
              rows={2}
            />

            <div style={styles.fotografSatiri}>
              <input
                ref={(el) => (fileInputRefs.current[t.id] = el)}
                type="file"
                accept="image/*"
                capture="environment"
                style={{ display: "none" }}
                onChange={(e) => onPhotoSelect(t.id, e.target.files[0])}
              />
              <button
                style={{ ...styles.fotoButon, opacity: duzenlenebilir ? 1 : 0.6 }}
                disabled={!duzenlenebilir}
                onClick={() => fileInputRefs.current[t.id] && fileInputRefs.current[t.id].click()}
              >
                {t.photo ? "Fotoğrafı Değiştir" : "📷 Fotoğraf Ekle"}
              </button>
              {t.photo && (
                <div style={styles.fotoOnizlemeSarmalayici}>
                  <img src={t.photo} alt={`Görev ${t.id} fotoğrafı`} style={styles.fotoOnizleme} />
                  {duzenlenebilir && (
                    <button
                      style={styles.fotoSilButon}
                      onClick={() => onRemovePhoto(t.id)}
                      aria-label="Fotoğrafı kaldır"
                    >
                      ✕
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
          );
        })}
      </div>

      {hata && <div style={{ ...styles.hataKutusu, marginTop: 16 }}>{hata}</div>}

      {duzenlenebilir ? (
        <button
          style={{ ...styles.anaButon, marginTop: 20, marginBottom: 24, opacity: bitiriliyor ? 0.7 : 1 }}
          onClick={onBitir}
          disabled={bitiriliyor}
        >
          {bitiriliyor ? "Kaydediliyor…" : "Bitir ve Kaydet"}
        </button>
      ) : (
        <div style={{ ...styles.bilgiKutusu, marginTop: 20, marginBottom: 24 }}>
          İşaretlemeleriniz otomatik olarak kaydedildi. 08:00–16:00 dışında düzenleme yapılamaz.
        </div>
      )}
    </div>
  );
}

function GecmisEkrani({ kayitlar, yukleniyor, onGeri, onPdf, jsPdfHazirMi }) {
  return (
    <div style={styles.icerik}>
      <div style={styles.listeUstBaslik}>
        <button style={styles.geriButon} onClick={onGeri} aria-label="Geri">
          ←
        </button>
        <div className="baslik-font" style={styles.listeBaslikYazi}>
          Geçmiş Kayıtlar
        </div>
      </div>

      {yukleniyor ? (
        <div style={styles.merkezYukleniyor}>Yükleniyor…</div>
      ) : kayitlar.length === 0 ? (
        <div style={{ color: "#6B7280", marginTop: 24, fontSize: 14 }}>
          Bu departman için henüz kayıtlı bir kontrol listesi bulunmuyor.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 16 }}>
          {kayitlar.map((k, i) => {
            const olumsuz = k.tasks.filter((t) => t.status === "olumsuz").length;
            const isaretli = k.tasks.filter((t) => t.status).length;
            return (
              <div key={i} style={styles.gecmisKarti}>
                <div style={{ display: "flex", justifyContent: "space-between" }}>
                  <strong style={{ color: "#16323A" }}>{formatTarihSadece(k.date)}</strong>
                  <span style={{ fontSize: 12, color: "#6B7280" }}>{k.userName}</span>
                </div>
                <div style={{ fontSize: 12, color: "#6B7280", marginTop: 4 }}>
                  {isaretli}/{k.tasks.length} madde · {k.tamamlandiMi ? "Tamamlandı" : "Süre içinde tamamlanmadı"}
                </div>
                <div
                  style={{
                    marginTop: 6,
                    fontSize: 12,
                    fontWeight: 600,
                    color: olumsuz > 0 ? "#B7472A" : "#2F7D5C",
                  }}
                >
                  {olumsuz > 0 ? `${olumsuz} olumsuz madde` : "Tüm maddeler olumlu"}
                </div>
                <button
                  style={styles.kucukPdfButon}
                  onClick={() => onPdf(k)}
                  title={jsPdfHazirMi() ? "" : "PDF oluşturucu hazırlanıyor"}
                >
                  📄 PDF Oluştur
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function Etiket({ children }) {
  return <div style={styles.etiket}>{children}</div>;
}

